impl CapabilityClient for PrivacyRequestAdminClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            list_activity: dependencies.one::<PrivacyRequestAdminListActivity>()?,
            list_admin_requests: dependencies.one::<PrivacyRequestAdminListAdminRequests>()?,
            pause_request: dependencies.one::<PrivacyRequestAdminPauseRequest>()?,
            reject_request: dependencies.one::<PrivacyRequestAdminRejectRequest>()?,
            resume_request: dependencies.one::<PrivacyRequestAdminResumeRequest>()?,
            set_legal_hold: dependencies.one::<PrivacyRequestAdminSetLegalHold>()?,
            verify_identity: dependencies.one::<PrivacyRequestAdminVerifyIdentity>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for PrivacyRequestAdminClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    list_activity: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminListActivity>()?,
                    list_admin_requests: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminListAdminRequests>()?,
                    pause_request: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminPauseRequest>()?,
                    reject_request: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminRejectRequest>()?,
                    resume_request: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminResumeRequest>()?,
                    set_legal_hold: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminSetLegalHold>()?,
                    verify_identity: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PrivacyRequestAdminVerifyIdentity>()?,
                    },
                ))
            })
            .collect()
    }
}

